import type { Question, AnswerOption, QuestionType } from '@jumbo/shared';

/**
 * Extract text from a user-uploaded PDF file in the browser.
 * Uses coordinate-aware line reconstruction so that text cells
 * generated by FPDF, Word, or LaTeX are reconstructed as exact visual lines.
 */
export async function extractTextFromPdfFile(file: File): Promise<string> {
  const arrayBuffer = await file.arrayBuffer();

  try {
    const pdfjsLib = await import('pdfjs-dist');
    if (pdfjsLib.GlobalWorkerOptions && !pdfjsLib.GlobalWorkerOptions.workerSrc) {
      pdfjsLib.GlobalWorkerOptions.workerSrc = `https://unpkg.com/pdfjs-dist@${
        pdfjsLib.version || '4.0.379'
      }/build/pdf.worker.min.mjs`;
    }

    const pdf = await ((await pdfjsLib.getDocument({ data: arrayBuffer }).promise) as any);
    let fullText = '';

    for (let pageNum = 1; pageNum <= pdf.numPages; pageNum++) {
      const page = await pdf.getPage(pageNum);
      const textContent = await page.getTextContent();
      const rawItems: any[] = textContent.items || [];

      // Collect all items with coordinates
      const validItems: { str: string; x: number; y: number; hasEOL?: boolean }[] = [];
      for (const it of rawItems) {
        if ('str' in it && typeof it.str === 'string' && it.str.trim().length > 0) {
          const transform = it.transform || [];
          validItems.push({
            str: it.str,
            x: typeof transform[4] === 'number' ? transform[4] : 0,
            y: typeof transform[5] === 'number' ? transform[5] : 0,
            hasEOL: Boolean(it.hasEOL),
          });
        }
      }

      // Group items into visual lines based on Y coordinate proximity
      // Use a tolerance of 3 points to handle slight baseline variations
      const YTOL = 3;
      const lineGroups: { y: number; items: { str: string; x: number }[] }[] = [];

      for (const item of validItems) {
        // Find an existing line group within Y tolerance
        let group = lineGroups.find((g) => Math.abs(g.y - item.y) <= YTOL);
        if (!group) {
          group = { y: item.y, items: [] };
          lineGroups.push(group);
        }
        group.items.push({ str: item.str, x: item.x });

        // If hasEOL, force a new line after this item
        if (item.hasEOL) {
          group.y = -9999 - lineGroups.length; // prevent future items from joining
        }
      }

      // Sort line groups by descending Y (PDF Y=0 is bottom, higher = upper on page)
      lineGroups.sort((a, b) => b.y - a.y);

      const pageLines = lineGroups.map((g) => {
        g.items.sort((a, b) => a.x - b.x);
        return g.items.map((c) => c.str).join(' ').trim();
      }).filter(Boolean);

      fullText += '\n' + pageLines.join('\n');
    }

    if (fullText.trim().length > 20) {
      return fullText;
    }
  } catch (err) {
    console.warn('pdfjs-dist failed, falling back to ASCII extraction:', err);
  }

  return extractAsciiStrings(arrayBuffer);
}

/** Basic ASCII/UTF-8 string extractor for uncompressed PDFs */
function extractAsciiStrings(buffer: ArrayBuffer): string {
  const uint8 = new Uint8Array(buffer);
  let result = '';
  let currentString = '';

  for (let i = 0; i < uint8.length; i++) {
    const code = uint8[i]!;
    if ((code >= 32 && code <= 126) || code === 10 || code === 13 || code === 9) {
      currentString += String.fromCharCode(code);
    } else {
      if (currentString.length >= 4) result += currentString + ' ';
      currentString = '';
    }
  }
  return result;
}

// ─── Regex constants (pre-compiled) ──────────────────────────────────────────

// Matches question starters: "1.", "1)", "(1)", "Q1.", "Q1:", "Question 1.", "Problem 1:", "Item 1:"
const Q_START_RE =
  /^(?:(?:Q(?:uestion)?|Item|Problem|No\.?)\s*#?\s*)?(\d{1,3})\s*[\.\:\-\)\]]/i;

// Matches option lines: "A.", "A)", "(A)", "a.", "1.", "(1)", etc.
const OPT_LINE_RE =
  /^(?:\(([A-Fa-f1-6])\)|([A-Fa-f1-6])[\.\:\-\)])\s*(.+)/;

// Matches answer key declarations: "Answer: B", "Ans: C", "Correct answer: A", etc.
const INLINE_ANS_RE =
  /(?:Answer|Ans(?:wer)?|Correct(?:\s+answer)?|Key|Solution)\s*(?:key|option)?\s*[:=\-]\s*\(?([A-Fa-f]|True|False|T|F)\)?/i;

// Answer key section header
const KEY_SECTION_RE =
  /(?:(?:\n|\r\n|^)\s*(?:Answer\s*Key|Answers|Solutions?|Keys?)\s*:?\s*\n)([\s\S]+)$/i;

// Per-item in the key section: "1. C" or "1) C" or "1: C"
const KEY_ITEM_RE = /Q?(\d+)\s*[\.\:\-\)]\s*\(?([A-Fa-f]|True|False|T|F)\)?/gi;

/**
 * Main public API: parse questions, options, and answers from raw text.
 * Handles: FPDF, standard exam formats, answer keys, inline answers,
 * multi-option lines, True/False, Multiple Choice, and Puzzle questions.
 */
export function parseQuestionsFromRawText(rawText: string): Question[] {
  if (!rawText || !rawText.trim()) return [];

  // ── Pass 1: Extract trailing Answer Key section ───────────────────────────
  const docAnswerKey = new Map<number, string>();
  let mainText = rawText;

  const keySectionMatch = rawText.match(KEY_SECTION_RE);
  if (keySectionMatch && keySectionMatch[1]) {
    mainText = rawText.slice(0, keySectionMatch.index);
    let km: RegExpExecArray | null;
    KEY_ITEM_RE.lastIndex = 0;
    while ((km = KEY_ITEM_RE.exec(keySectionMatch[1])) !== null) {
      if (km[1] && km[2]) {
        docAnswerKey.set(parseInt(km[1], 10), km[2].trim().toUpperCase());
      }
    }
  }

  // ── Pass 2: Normalize lines & split inline multi-option lines ─────────────
  const rawLines = mainText.split(/\r?\n/);
  const normalizedLines: string[] = [];

  for (const rawLine of rawLines) {
    const line = rawLine.trim();
    if (!line) {
      normalizedLines.push('');
      continue;
    }

    // Detect "A. Option1 B. Option2 C. Option3" packed into one line
    const MULTI_OPT_RE = /(?:^|\s+)(?:\(([A-Fa-f1-6])\)|([A-Fa-f1-6])[\.\)])\s+/g;
    const hits = [...line.matchAll(MULTI_OPT_RE)];
    if (hits.length >= 2) {
      // Split at each option marker boundary
      for (let i = 0; i < hits.length; i++) {
        const start = hits[i]!.index ?? 0;
        const end = i + 1 < hits.length ? (hits[i + 1]!.index ?? line.length) : line.length;
        const chunk = line.slice(start, end).trim();
        if (chunk) normalizedLines.push(chunk);
      }
    } else {
      normalizedLines.push(line);
    }
  }

  const cleanText = normalizedLines.join('\n');

  // ── Pass 3: Identify question-start line positions ────────────────────────
  // Strategy: scan every line, find those matching Q_START_RE.
  // Build an array of { lineIdx, qNum } to know question boundaries.
  const allLines = cleanText.split('\n');
  const qStartPositions: { lineIdx: number; qNum: number }[] = [];

  for (let i = 0; i < allLines.length; i++) {
    const line = allLines[i]!.trim();
    if (!line) continue;
    const m = line.match(Q_START_RE);
    if (m && m[1]) {
      const num = parseInt(m[1], 10);
      // Avoid false positives: the number must be 1, or close to the previous Q number
      const lastNum = qStartPositions.length > 0
        ? qStartPositions[qStartPositions.length - 1]!.qNum
        : 0;
      // Accept: num === 1, or num === lastNum+1, or (for flexibility) num <= lastNum+3
      if (num === 1 || num <= lastNum + 3) {
        qStartPositions.push({ lineIdx: i, qNum: num });
      }
    }
  }

  // If no numbered questions found, try a looser approach:
  // treat any line matching a question pattern (ends with ?) as a question
  if (qStartPositions.length === 0) {
    return parseLoose(cleanText, docAnswerKey);
  }

  // ── Pass 4: Build question blocks from identified boundaries ──────────────
  const questions: Question[] = [];

  for (let qi = 0; qi < qStartPositions.length; qi++) {
    const { lineIdx, qNum } = qStartPositions[qi]!;
    const nextLineIdx = qi + 1 < qStartPositions.length
      ? qStartPositions[qi + 1]!.lineIdx
      : allLines.length;

    const blockLines = allLines.slice(lineIdx, nextLineIdx)
      .map((l) => l.trim())
      .filter(Boolean);

    if (blockLines.length === 0) continue;

    const docAnswer = docAnswerKey.get(qNum);
    const parsed = parseSingleBlock(blockLines, qNum, docAnswer);
    if (parsed) questions.push(parsed);
  }

  return questions;
}

/**
 * Loose parser for text without numbered questions —
 * looks for question-ending '?' lines and collects following options.
 */
function parseLoose(text: string, docAnswerKey: Map<number, string>): Question[] {
  const questions: Question[] = [];
  const lines = text.split('\n').map((l) => l.trim()).filter(Boolean);
  let i = 0;
  let qNum = 1;

  while (i < lines.length) {
    const line = lines[i]!;
    // Potential question prompt: ends with '?' OR is a long sentence
    if (line.endsWith('?') || (line.length > 20 && !OPT_LINE_RE.test(line))) {
      const blockLines: string[] = [line];
      i++;
      // Collect subsequent option lines
      while (i < lines.length && OPT_LINE_RE.test(lines[i]!)) {
        blockLines.push(lines[i]!);
        i++;
      }
      // Only treat as a question if we have at least one option
      if (blockLines.length >= 2 || line.endsWith('?')) {
        const parsed = parseSingleBlock(blockLines, qNum, docAnswerKey.get(qNum));
        if (parsed) { questions.push(parsed); qNum++; }
      }
    } else {
      i++;
    }
  }

  return questions;
}

/**
 * Parse a single question block (array of trimmed lines) into a Question object.
 * blockLines[0] is the question prompt line (may still have "1." prefix).
 */
function parseSingleBlock(
  blockLines: string[],
  index: number,
  docAnswer?: string,
): Question | null {
  if (blockLines.length === 0) return null;

  // ── Extract question prompt ──────────────────────────────────────────────
  let prompt = blockLines[0]!
    .replace(Q_START_RE, '')
    .trim();

  // If prompt is empty after stripping number, take next line
  let startOptIdx = 1;
  if (!prompt && blockLines.length > 1 && !OPT_LINE_RE.test(blockLines[1]!)) {
    prompt = blockLines[1]!.replace(Q_START_RE, '').trim();
    startOptIdx = 2;
  }

  // Multi-line prompt: keep appending until we hit an option line or answer line
  for (let i = startOptIdx; i < blockLines.length; i++) {
    const line = blockLines[i]!;
    if (OPT_LINE_RE.test(line)) { startOptIdx = i; break; }
    if (INLINE_ANS_RE.test(line)) { startOptIdx = i; break; }
    // It's a continuation of the prompt
    prompt += ' ' + line;
    startOptIdx = i + 1;
  }

  prompt = prompt.trim();

  // ── Detect inline answer ─────────────────────────────────────────────────
  let markedAnswer = docAnswer || '';
  for (const line of blockLines) {
    const ansMatch = line.match(INLINE_ANS_RE);
    if (ansMatch && ansMatch[1] && !markedAnswer) {
      markedAnswer = ansMatch[1].trim().toUpperCase();
      break;
    }
  }

  // Also scan answer marked inline in options (star, checkmark, "(Correct)")
  // ── Parse answer options ─────────────────────────────────────────────────
  const parsedOptions: { id: string; letter: string; text: string; isCorrect: boolean }[] = [];

  for (let i = startOptIdx; i < blockLines.length; i++) {
    const line = blockLines[i]!;

    // Skip answer key lines
    if (INLINE_ANS_RE.test(line)) continue;

    const m = line.match(OPT_LINE_RE);
    if (m) {
      const letter = (m[1] || m[2] || '').toUpperCase();
      let text = (m[3] || '').trim();

      // Detect correct-answer markers in text
      let isCorrect =
        text.startsWith('*') ||
        text.includes('(Correct)') ||
        text.includes('[x]') ||
        text.includes('[X]') ||
        text.includes('✓');

      // Clean markers from text
      text = text
        .replace(/^\*\s*/, '')
        .replace(/\s*\(Correct\)\s*$/i, '')
        .replace(/\s*\[x\]\s*$/i, '')
        .replace(/\s*✓\s*$/, '')
        .trim();

      if (text) {
        parsedOptions.push({
          id: `opt_${index}_${parsedOptions.length + 1}`,
          letter,
          text,
          isCorrect,
        });
      }
    }
  }

  // ── Determine question type ───────────────────────────────────────────────
  // STRICT True/False detection:
  // Only classify as T/F if the question itself contains "true or false" language,
  // OR if the answer key says "TRUE"/"FALSE",
  // OR if the two extracted options are literally "True" and "False" text.
  // Never classify as T/F just because there are 2 options.
  const hasTFLanguage =
    /\b(?:true\s*or\s*false|true\s*\/\s*false|t\s*\/\s*f)\b/i.test(prompt) ||
    /\b(?:true\s*or\s*false|true\s*\/\s*false|t\s*\/\s*f)\b/i.test(blockLines.join(' '));

  const optTextsAreTF =
    parsedOptions.length === 2 &&
    parsedOptions.some((o) => /^true$/i.test(o.text)) &&
    parsedOptions.some((o) => /^false$/i.test(o.text));

  const answerIsTF =
    markedAnswer === 'TRUE' || markedAnswer === 'FALSE' ||
    markedAnswer === 'T' || markedAnswer === 'F';

  // Only mark as T/F if there's explicit T/F evidence
  const isTF = hasTFLanguage || optTextsAreTF || (answerIsTF && parsedOptions.length <= 2);

  const isPuzzle =
    parsedOptions.length >= 3 &&
    /\b(?:order|arrange|chronological|sequence|rank|sort|first|last)\b/i.test(prompt);

  // If not enough info, skip (but only if not a T/F question)
  if (!isTF && parsedOptions.length < 2 && !isPuzzle) {
    // If there's a prompt and doc answer but no parsed options, attempt reconstruction
    if (prompt && docAnswer && /^[A-F]$/i.test(docAnswer)) {
      // We know answer but options weren't parsed — return with placeholder options
      // (user can edit in the review screen)
      const fallbackOpts: AnswerOption[] = ['A', 'B', 'C', 'D'].map((l, idx) => ({
        id: `opt_${index}_${idx + 1}`,
        text: `Option ${l}`,
        isCorrect: l === docAnswer.toUpperCase(),
      }));
      return {
        id: `extracted_${index}_${Date.now()}`,
        type: 'multiple_choice',
        text: prompt || `Question ${index}`,
        options: fallbackOpts,
        timeLimit: 20,
        category: 'Custom & Imported',
        difficulty: 'medium',
        points: 1000,
      };
    }
    if (!prompt) return null;
    // If prompt exists but no options, still create with placeholder options
    const fallbackOpts: AnswerOption[] = ['A', 'B', 'C', 'D'].map((l, idx) => ({
      id: `opt_${index}_${idx + 1}`,
      text: `Option ${l}`,
      isCorrect: idx === 0,
    }));
    return {
      id: `extracted_${index}_${Date.now()}`,
      type: 'multiple_choice',
      text: prompt,
      options: fallbackOpts,
      timeLimit: 20,
      category: 'Custom & Imported',
      difficulty: 'medium',
      points: 1000,
    };
  }

  const qType: QuestionType = isPuzzle
    ? 'puzzle'
    : isTF
    ? 'true_false'
    : 'multiple_choice';

  // ── Build final options ───────────────────────────────────────────────────
  let finalOptions: AnswerOption[] = [];

  if (qType === 'true_false') {
    // Determine correct T/F answer
    let isTrue: boolean;
    if (markedAnswer === 'TRUE' || markedAnswer === 'T') {
      isTrue = true;
    } else if (markedAnswer === 'FALSE' || markedAnswer === 'F') {
      isTrue = false;
    } else if (markedAnswer === 'A') {
      // 'A' usually corresponds to True in exam keys
      isTrue = true;
    } else if (markedAnswer === 'B') {
      isTrue = false;
    } else {
      // Detect from parsed options
      const trueOpt = parsedOptions.find((o) => /^true$/i.test(o.text));
      isTrue = trueOpt ? trueOpt.isCorrect : true;
    }
    finalOptions = [
      { id: `opt_${index}_true`, text: 'True', isCorrect: isTrue },
      { id: `opt_${index}_false`, text: 'False', isCorrect: !isTrue },
    ];

  } else if (qType === 'puzzle') {
    finalOptions = parsedOptions.slice(0, 8).map((o, idx) => ({
      id: o.id || `puz_${index}_${idx + 1}`,
      text: o.text || `Step ${idx + 1}`,
      isCorrect: true,
    }));

  } else {
    // Multiple choice: apply doc answer key if available
    if (markedAnswer && /^[A-F]$/i.test(markedAnswer)) {
      const targetLetter = markedAnswer.toUpperCase();
      parsedOptions.forEach((o, idx) => {
        // Match by letter if available, else by position
        o.isCorrect = o.letter ? o.letter === targetLetter : idx === (targetLetter.charCodeAt(0) - 65);
      });
    }

    // Ensure at least one option is marked correct
    if (!parsedOptions.some((o) => o.isCorrect)) {
      if (parsedOptions.length > 0) parsedOptions[0]!.isCorrect = true;
    }

    finalOptions = parsedOptions.slice(0, 6).map((o, idx) => ({
      id: o.id || `opt_${index}_${idx + 1}`,
      text: o.text || `Option ${idx + 1}`,
      isCorrect: Boolean(o.isCorrect),
    }));

    // If still no options (edge case), add placeholder options
    if (finalOptions.length < 2) {
      finalOptions = ['A', 'B', 'C', 'D'].map((l, idx) => ({
        id: `opt_${index}_${idx + 1}`,
        text: `Option ${l}`,
        isCorrect: idx === 0,
      }));
    }
  }

  return {
    id: `extracted_${index}_${Date.now()}`,
    type: qType,
    text: prompt || `Question ${index}`,
    options: finalOptions,
    timeLimit: 20,
    category: 'Custom & Imported',
    difficulty: 'medium',
    points: 1000,
    correctOrder: qType === 'puzzle' ? finalOptions.map((o) => o.id) : undefined,
  };
}
